from dataclasses import dataclass


CANCELLABLE_STATES = frozenset({"pending", "cancelled"})


@dataclass
class Order:
    id: int
    state: str


def cancel(order: Order) -> bool:
    if order.state not in CANCELLABLE_STATES:
        return False
    order.state = "cancelled"
    return True

